1	package org.jsoup.internal;
2	
3	import org.jsoup.Progress;
4	import org.jsoup.helper.Validate;
5	import org.jspecify.annotations.Nullable;
6	
7	import java.io.BufferedInputStream;
8	import java.io.FilterInputStream;
9	import java.io.IOException;
10	import java.io.InputStream;
11	import java.net.SocketTimeoutException;
12	import java.nio.ByteBuffer;
13	import java.util.function.Supplier;
14	
15	import static org.jsoup.internal.SharedConstants.DefaultBufferSize;
16	
17	/**
18	 * A jsoup internal class (so don't use it as there is no contract API) that enables controls on a buffered input stream,
19	 * namely a maximum read size, and the ability to Thread.interrupt() the read.
20	 */
21	// reimplemented from ConstrainableInputStream for JDK21 - extending BufferedInputStream will pin threads during read
22	public class ControllableInputStream extends FilterInputStream {
23	    private final SimpleBufferedInput buff; // super.in, but typed as SimpleBufferedInput
24	    private int maxSize;                    // logical cap exposed to callers (0 == unlimited)
25	    private long startTime;                 // start time for timeout checks, nanos
26	    private long timeout = 0;               // optional max time of request
27	    private int remaining;                  // how many bytes may still be returned to caller under the current cap
28	    private int markPos;                    // logical readPos snapshot for InputStream.mark/reset (not a buffer cursor)
29	    private boolean interrupted;            // true if Thread.interrupted() was detected, used to latch interrupted state
30	    private boolean truncated;              // true if there is content beyond the body cap
31	    private boolean allowClose = true;      // for cases where we want to re-read the input, can ignore .close() from the parser
32	    private final byte[] singleByte = new byte[1]; // avoids allocation when routing single-byte reads through controls
33	
34	    // if we are tracking progress, supplies the currently bound handler (re-read live on every event); a null result
35	    // means no handler is registered (cancelled or replaced), so that switching or removing a handler takes effect
36	    // immediately without re-registering the stream.
37	    private @Nullable Supplier<? extends @Nullable Handle<?>> progressSource;
38	    private @Nullable Object lastCallback;       // callback last notified, to detect a live switch to a new handler
39	    private int contentLength = -1;         // declared content length for progress; -1 == unknown
40	    private boolean successful = true;     // whether the response was a successful status; failures never report completion
41	    private int readPos = 0;                // logical amount read; can move backwards on reset()
42	    private int highWater = 0;              // furthest logical position ever read; progress never reports below this
43	    private int lastEmitted = -1;           // last processed value emitted, to suppress duplicate re-read events
44	    private boolean emittedInitial = false; // the initial (0, total, 0%) event has been emitted
45	    private boolean completed = false;      // the terminal completion event has been emitted
46	    private boolean lengthMismatch = false; // delivered bytes disagreed with the declared length; never complete
47	    private ControllableInputStream(SimpleBufferedInput in, int maxSize) {
48	        super(in);
49	        Validate.isTrue(maxSize >= 0);
50	        buff = in;
51	        this.maxSize = maxSize;
52	        remaining = maxSize;
53	        markPos = -1;
54	        startTime = System.nanoTime();
55	    }
56	
57	    /**
58	     * If this InputStream is not already a ControllableInputStream, let it be one.
59	     * @param in the input stream to (maybe) wrap. A {@code null} input will create an empty wrapped stream.
60	     * @param maxSize the maximum size to allow to be read. 0 == infinite.
61	     * @return a controllable input stream
62	     */
63	    public static ControllableInputStream wrap(@Nullable InputStream in, int maxSize) {
64	        // bufferSize currently unused; consider implementing as a min size in the SoftPool recycler
65	        if (in instanceof ControllableInputStream)
66	            return (ControllableInputStream) in;
67	        else
68	            return new ControllableInputStream(new SimpleBufferedInput(in), maxSize);
69	    }
70	
71	    /**
72	     * If this InputStream is not already a ControllableInputStream, let it be one.
73	     * @param in the input stream to (maybe) wrap
74	     * @param bufferSize the buffer size to use when reading
75	     * @param maxSize the maximum size to allow to be read. 0 == infinite.
76	     * @return a controllable input stream
77	     */
78	    public static ControllableInputStream wrap(InputStream in, int bufferSize, int maxSize) {
79	        // todo - bufferSize currently unused; consider implementing as a min size in the SoftPool recycler; or just deprecate if always DefaultBufferSize
80	        return wrap(in, maxSize);
81	    }
82	
83	    @Override
84	    public int read() throws IOException {
85	        int read = read(singleByte, 0, 1); // route through the controlled read, so caps and progress account for single-byte reads
86	        return read == -1 ? -1 : singleByte[0] & 0xff;
87	    }
88	
89	    @Override
90	    public int read(byte[] b, int off, int len) throws IOException {
91	        emitInitialProgress();
92	
93	        boolean capped = maxSize != 0;
94	        if (interrupted)
95	            return -1;
96	        if (Thread.currentThread().isInterrupted()) {
97	            // interrupted latches, because parse() may call twice
98	            interrupted = true;
99	            return -1;
100	        }
101	        if (capped && remaining <= 0) {
102	            if (checkTruncated()) return -1; // more content exists beyond the cap: this is a truncation, not an end of entity
103	            complete(); // entity ended exactly on the cap
104	            return -1;
105	        }
106	
107	        if (capped && len > remaining)
108	            len = remaining; // don't read more than desired, even if available
109	        if (capped) buff.capRemaining(remaining);
110	        else buff.uncap();
111	
112	        while (true) { // loop trying to read until we get some data or hit the overall timeout, if we have one
113	            if (expired())
114	                throw new SocketTimeoutException("Read timeout");
115	
116	            try {
117	                final int read = super.read(b, off, len);
118	                if (read == -1) { // the underlying entity genuinely ended
119	                    complete();
120	                } else {
121	                    if (capped && read > 0) {
122	                        remaining -= read; // track bytes returned to the caller
123	                    }
124	                    // todo: use long progress values in the public API; saturate until that is available
125	                    readPos = read > Integer.MAX_VALUE - readPos ? Integer.MAX_VALUE : readPos + read;
126	                    emitProgress();
127	                }
128	                return read;
129	            } catch (SocketTimeoutException e) {
130	                if (expired() || timeout == 0)
131	                    throw e;
132	            }
133	        }
134	    }
135	
136	    @Override
137	    public long skip(long requested) throws IOException {
138	        // implemented here so our cap accounting and progress stay aligned with actual reads
139	        if (requested <= 0) return 0;
140	
141	        byte[] skipBuffer = SimpleBufferedInput.BufferPool.borrow();
142	        long skipped = 0;
143	        try {
144	            while (skipped < requested) {
145	                int read = read(skipBuffer, 0, (int) Math.min(requested - skipped, skipBuffer.length));
146	                if (read == -1) break;
147	                skipped += read;
148	            }
149	            return skipped;
150	        } finally {
151	            SimpleBufferedInput.BufferPool.release(skipBuffer);
152	        }
153	    }
154	
155	    @Override
156	    public boolean markSupported() {
157	        return true;
158	    }
159	
160	    /**
161	     * Reads this inputstream to a ByteBuffer. The supplied max may be less than the inputstream's max, to support
162	     * reading just the first bytes.
163	     */
164	    public static ByteBuffer readToByteBuffer(InputStream in, int max) throws IOException {
165	        Validate.isTrue(max >= 0, "maxSize must be 0 (unlimited) or larger");
166	        Validate.notNull(in);
167	        final boolean capped = max > 0;
168	        final byte[] readBuf = SimpleBufferedInput.BufferPool.borrow(); // Share the same byte[] pool as SBI
169	        final int outSize = capped ? Math.min(max, DefaultBufferSize) : DefaultBufferSize;
170	        ByteBuffer outBuf = ByteBuffer.allocate(outSize);
171	
172	        try {
173	            int remaining = max;
174	            int read;
175	            while ((read = in.read(readBuf, 0, capped ? Math.min(remaining, DefaultBufferSize) : DefaultBufferSize)) != -1) {
176	                if (outBuf.remaining() < read) { // needs to grow
177	                    int newCapacity = (int) Math.max(outBuf.capacity() * 1.5, outBuf.capacity() + read);
178	                    ByteBuffer newBuffer = ByteBuffer.allocate(newCapacity);
179	                    outBuf.flip();
180	                    newBuffer.put(outBuf);
181	                    outBuf = newBuffer;
182	                }
183	                outBuf.put(readBuf, 0, read);
184	                if (capped) {
185	                    remaining -= read;
186	                    if (remaining <= 0) break;
187	                }
188	            }
189	            outBuf.flip(); // Prepare the buffer for reading
190	            return outBuf;
191	        } finally {
192	            SimpleBufferedInput.BufferPool.release(readBuf);
193	        }
194	    }
195	
196	    @SuppressWarnings("NonSynchronizedMethodOverridesSynchronizedMethod") // not synchronized in later JDKs
197	    @Override public void reset() throws IOException {
198	        if (markPos < 0) throw new IOException("Resetting to invalid mark");
199	        buff.rewindToMark();
200	        buff.clearMark();
201	        truncated = false;
202	        if (maxSize != 0) {
203	            remaining = maxSize - markPos;
204	            buff.capRemaining(remaining);
205	        } else {
206	            remaining = 0;
207	            buff.uncap();
208	        }
209	        readPos = markPos; // logical position rewinds; highWater keeps delivered progress monotonic across the re-read
210	        markPos = -1;
211	    }
212	
213	    @SuppressWarnings("NonSynchronizedMethodOverridesSynchronizedMethod")
214	    @Override public void mark(int readlimit) {
215	        markPos = readPos;
216	        buff.setMark();
217	    }
218	
219	    /**
220	     Check if the underlying InputStream has been read fully. There may still content in buffers to be consumed, and
221	     read methods may return -1 if hit the read limit.
222	     @return true if the underlying inputstream has been read fully.
223	     */
224	    public boolean baseReadFully() {
225	        return buff.baseReadFully();
226	    }
227	
228	    public void resetFullyRead() {
229	        buff.resetFullyRead();
230	    }
231	
232	    /**
233	     Get the max size of this stream (how far at most will be read from the underlying stream)
234	     * @return the max size
235	     */
236	    public int max() {
237	        return maxSize;
238	    }
239	
240	    public void max(int newMax) {
241	        remaining += newMax - maxSize; // update remaining to reflect the difference in the new maxsize
242	        if (remaining < 0) remaining = 0;
243	        if (newMax == 0 || newMax > maxSize) truncated = false;
244	        maxSize = newMax;
245	        if (newMax == 0) buff.uncap();
246	        else buff.capRemaining(remaining);
247	    }
248	
249	    /**
250	     Probes whether content remains beyond the configured cap, without pulling that content into the logical stream.
251	     @return true if the entity was truncated by the cap; false if the cap was reached at a genuine end of entity
252	     */
253	    public boolean checkTruncated() throws IOException {
254	        while (!truncated && maxSize != 0 && remaining <= 0) {
255	            if (expired()) throw new SocketTimeoutException("Read timeout");
256	            try {
257	                truncated = buff.hasMore();
258	                break;
259	            } catch (SocketTimeoutException e) {
260	                if (expired() || timeout == 0) throw e;
261	            }
262	        }
263	        return truncated;
264	    }
265	
266	    /**
267	     Returns whether content was found beyond the configured cap.
268	     */
269	    public boolean isTruncated() {
270	        return truncated;
271	    }
272	
273	    public void allowClose(boolean allowClose) {
274	        this.allowClose = allowClose;
275	    }
276	
277	    @Override public void close() throws IOException {
278	        if (allowClose) super.close();
279	    }
280	
281	    public ControllableInputStream timeout(long startTimeNanos, long timeoutMillis) {
282	        this.startTime = startTimeNanos;
283	        this.timeout = timeoutMillis * 1000000;
284	        return this;
285	    }
286	
287	    /**
288	     * Opens progress observation on the first controlled read. A declared length of zero is an already-complete
289	     * entity, so its one and only event is the terminal completion; a positive declared length gets an initial
290	     * {@code (0, total, 0%)} event. An unknown length has no determinable start, so its initial event is deferred
291	     * until bytes actually arrive (see {@link #emitProgress()}), which lets an unknown-length empty entity produce
292	     * only its single terminal completion.
293	     */
294	    private void emitInitialProgress() {
295	        Handle<?> handle = activeHandle();
296	        if (emittedInitial || handle == null) return;
297	        emittedInitial = true;
298	        if (contentLength == 0) { // a declared-empty entity: nothing can ever be read, so complete exactly once
299	            complete();
300	        } else if (contentLength > 0) {
301	            // a declared length starts with a determinable (0, total, 0%) event
302	            int processed = reportedProcessed();
303	            lastEmitted = processed;
304	            float percent = Math.min(100f, processed * 100f / contentLength);
305	            deliver(handle, processed, contentLength, percent);
306	        }
307	        // an unknown length has no determinable start: hold the initial event until bytes actually arrive (handled in
308	        // emitProgress), so an unknown-length empty entity yields only its single terminal completion
309	    }
310	
311	    /**
312	     Emits an intermediate progress event, unless the logical position is being re-read after a reset, in which case
313	     the already-reported high-water position is held so that progress never moves backwards or repeats.
314	     */
315	    private void emitProgress() {
316	        Handle<?> handle = activeHandle();
317	        if (handle == null) return;
318	        int processed = reportedProcessed();
319	        // an unknown length delays its initial event until bytes actually arrive (so an empty entity has no leading
320	        // 0% event); emit that single (0, -1, 0) before the first data event
321	        if (contentLength < 0 && lastEmitted < 0) {
322	            deliver(handle, 0, contentLength, 0f);
323	            lastEmitted = 0;
324	        }
325	        if (processed == lastEmitted) return; // re-reading buffered content after a reset: no new progress
326	        lastEmitted = processed;
327	        // calculate percent complete against the declared length; for an unknown length both percent stay at 0 and
328	        // total stays -1, right through to the terminal event
329	        float percent;
330	        if (contentLength > 0) {
331	            percent = processed * 100f / contentLength;
332	            // 100% is reserved for the single terminal event confirmed at end-of-entity; an intermediate read that
333	            // already meets the declared total (without an end-of-entity confirmation yet) reports just below it
334	            if (percent >= 100f) percent = Math.nextDown(100f);
335	        } else {
336	            percent = 0f;
337	        }
338	        deliver(handle, processed, contentLength, percent);
339	    }
340	
341	    /**
342	     * Resolves the handler currently bound to this stream, re-reading the live source on every event. If a different
343	     * callback instance is now bound, observation state restarts from the current logical position, so the new handler
344	     * neither inherits the previous handler's high-water/completion nor receives any of its earlier events; a null
345	     * source result means the handler was cancelled and no event is delivered.
346	     */
347	    private @Nullable Handle<?> activeHandle() {
348	        Supplier<? extends @Nullable Handle<?>> source = progressSource;
349	        if (source == null) return null;
350	        Handle<?> handle = source.get();
351	        if (handle == null) return null;
352	        if (handle.callback != lastCallback) {
353	            Object previous = lastCallback;
354	            lastCallback = handle.callback;
355	            restartObservation(false); // entity-level facts (length mismatch) carry over; observer counters do not
356	            if (previous != null) {
357	                // a live switch between two handlers: the event that discovered the newcomer is its first event, so
358	                // anchor it at the current position and suppress a separate (0,...) initial. It then observes from
359	                // where it was bound (no stale 0, no duplicate); the first binding / an explicit re-registration
360	                // leaves emittedInitial false and lastEmitted -1, so the normal initial event still fires.
361	                emittedInitial = true;
362	                lastEmitted = reportedProcessed();
363	            }
364	        }
365	        return handle;
366	    }
367	
368	    /**
369	     * Reports the processed byte count for an event: the furthest logical position actually delivered (held across a
370	     * mark/reset re-read so progress never walks backwards), clamped to a declared length so {@code processed} can
371	     * never exceed it. Delivering more bytes than were declared latches {@link #lengthMismatch} so no later event can
372	     * signal completion.
373	     */
374	    private int reportedProcessed() {
375	        if (readPos > highWater) highWater = readPos;
376	        int processed = highWater;
377	        if (contentLength > 0 && processed > contentLength) {
378	            lengthMismatch = true;
379	            processed = contentLength;
380	        }
381	        return processed;
382	    }
383	
384	    /**
385	     * Delegates a single progress event to the bound callback, isolating any {@link RuntimeException} it throws. The
386	     * callback is a side-channel observer: its exception is swallowed for this notification only and neither aborts
387	     * the network read, resource close, or parsing, nor suppresses any later notification (including completion), nor
388	     * leaks into another callback or the next request.
389	     */
390	    @SuppressWarnings("rawtypes")
391	    private static void deliver(Handle handle, int processed, int total, float percent) {
392	        try {
393	            //noinspection unchecked
394	            handle.callback.onProgress(processed, total, percent, handle.context);
395	        } catch (RuntimeException e) {
396	            // this notification only; reads, close, and subsequent notifications continue unaffected
397	        }
398	    }
399	
400	    /**
401	     * Emits the terminal event once the entity has been confirmed read to its end. A successful {@code 100%}
402	     * completion is emitted exactly once, only when the status is successful and the delivered entity matches the
403	     * declared length; {@code total} is then the declared length, or stays {@code -1} for an unknown length (the
404	     * actual delivered byte count is carried in {@code processed}). Reaching the configured cap while more content
405	     * exists never gets here (that is a truncation, handled by the caller); an unsuccessful status or a declared
406	     * length that did not match the actual entity reports only the partial delivery below {@code 100%}; an I/O
407	     * failure never calls this, so a failed read never reports completion or looks successful.
408	     */
409	    private void complete() {
410	        Handle<?> handle = activeHandle();
411	        if (handle == null || completed) return;
412	        completed = true;
413	        emittedInitial = true;
414	        if (readPos > highWater) highWater = readPos;
415	        int actual = highWater;
416	        boolean mismatch = contentLength > 0 && (lengthMismatch || actual != contentLength);
417	
418	        if (successful && !mismatch) {
419	            int processed = contentLength > 0 ? contentLength : actual;
420	            // an unknown length stays -1 even at the terminal event; processed carries the delivered byte count
421	            deliver(handle, processed, contentLength, 100f);
422	        } else {
423	            // unsuccessful status, or the entity did not match its declared length: report the bytes actually
424	            // delivered, but hold below completion and keep the declared total (-1 when unknown) so the caller never
425	            // mistakes it for a successful completion
426	            int processed = contentLength > 0 ? Math.min(actual, contentLength) : actual;
427	            float percent = contentLength > 0
428	                ? Math.min(Math.nextDown(100f), processed * 100f / contentLength)
429	                : 0f;
430	            deliver(handle, processed, contentLength, percent);
431	        }
432	    }
433	
434	    public <ProgressContext> ControllableInputStream onProgress(int contentLength, Progress<ProgressContext> callback, ProgressContext context) {
435	        return onProgress(contentLength, true, callback, context);
436	    }
437	
438	    public <ProgressContext> ControllableInputStream onProgress(int contentLength, boolean successful,
439	        Progress<ProgressContext> callback, ProgressContext context) {
440	        Validate.notNull(callback);
441	        Validate.notNull(context);
442	        return onProgress(contentLength, successful, () -> new Handle<>(callback, context));
443	    }
444	
445	    /**
446	     * Binds a live source for the active progress handler. The source is re-read for every event, so it may return a
447	     * different handler to replace the current one, or {@code null} to cancel it, while the response is being read;
448	     * the previously bound handler then immediately stops receiving events. Observation counters and completion
449	     * start independently for this binding, from the current logical read position.
450	     */
451	    public ControllableInputStream onProgress(int contentLength, boolean successful,
452	        Supplier<? extends @Nullable Handle<?>> source) {
453	        this.contentLength = contentLength;
454	        this.successful = successful;
455	        this.progressSource = source;
456	        this.lastCallback = null;
457	        restartObservation(true);
458	        return this;
459	    }
460	
461	    /** Resets per-observer progress state, optionally also clearing the entity-level declared-length mismatch. */
462	    private void restartObservation(boolean clearMismatch) {
463	        emittedInitial = false;
464	        completed = false;
465	        if (clearMismatch) lengthMismatch = false;
466	        lastEmitted = -1;
467	        highWater = readPos;
468	    }
469	
470	    private boolean expired() {
471	        if (timeout == 0)
472	            return false;
473	
474	        final long now = System.nanoTime();
475	        final long dur = now - startTime;
476	        return (dur > timeout);
477	    }
478	
479	    public BufferedInputStream inputStream() {
480	        // called via HttpConnection.Response.bodyStream(); that public stream is intentionally not subject to the
481	        // request's maxBodySize cap (parse/readFully are), so wrap the underlying buffer directly rather than this
482	        return new BufferedInputStream(buff);
483	    }
484	
485	    /**
486	     * Pairs a progress callback with the context object supplied to it on every event. Part of the internal progress
487	     * plumbing; produced by the live handler source passed to {@link #onProgress(int, boolean, Supplier)}.
488	     */
489	    public static final class Handle<ProgressContext> {
490	        final Progress<ProgressContext> callback;
491	        final ProgressContext context;
492	
493	        public Handle(Progress<ProgressContext> callback, ProgressContext context) {
494	            this.callback = callback;
495	            this.context = context;
496	        }
497	    }
498	}
