151	    /**
152	     As HTTP/2 no longer provides a server-set status message, and HttpClient doesn't parse it for 1.1, just provide minimal stock ones, for loggers.
153	     */
154	    static String StatusMessage(int statusCode) {
155	        if (statusCode < 400) return "OK";
156	        if (statusCode == 404) return "Not Found";
157	        return "Error " + statusCode;
158	    }
159	
160	    @Override
161	    InputStream responseBody() throws IOException {
162	        if (hRes == null) throw new IllegalStateException("Not yet executed");
163	        return hRes.body();
164	    }
165	
166	    @Override
167	    void safeClose() {
168	        if (hRes != null) {
169	            InputStream body = hRes.body();
170	            if (body != null) {
171	                try {
172	                    body.close();
173	                } catch (IOException ignored) {}
174	            }
175	            hRes = null;
176	        }
177	    }
