179	    static HttpRequest.BodyPublisher requestBody(final HttpConnection.Request req) throws IOException {
180	        if (!req.method.hasBody())
181	            return HttpRequest.BodyPublishers.noBody();
182	
183	        InputStream bodyStream = req.requestBodyStream();
184	        if (bodyStream != null) {
185	            // stream the upload so that the HttpClient does not buffer it before sending
186	            // a caller supplied stream is one-shot, so a replay gets nothing via an AtomicReference
187	            AtomicReference<InputStream> stream = new AtomicReference<>(bodyStream);
188	            return HttpRequest.BodyPublishers.ofInputStream(() -> stream.getAndSet(null));
189	        }
190	
191	        // other bodies are fields or text; need to serialize
