198	        // empty list for no proxy:
199	        static final List<Proxy> NoProxy = new ArrayList<>(0);
200	
201	        @Override
202	        public List<Proxy> select(URI uri) {
203	            Proxy proxy = perRequestProxy.get();
204	            if (proxy != null) {
205	                return Collections.singletonList(proxy);
206	            }
207	            ProxySelector defaultSelector = ProxySelector.getDefault();
208	            if (defaultSelector != null && defaultSelector != this) { // avoid recursion if we were set as default
209	                return defaultSelector.select(uri);
210	            }
211	            return NoProxy;
212	        }
213	
214	        @Override
215	        public void connectFailed(URI uri, SocketAddress sa, IOException ioe) {
216	            if (perRequestProxy.get() != null) {
217	                return;  // no-op
218	            }
219	            ProxySelector defaultSelector = ProxySelector.getDefault();
220	            if (defaultSelector != null && defaultSelector != this) {
221	                defaultSelector.connectFailed(uri, sa, ioe);
