20	    @Test
21	    void respectsMaxCapDuringFill() throws IOException {
22	        byte[] data = "0123456789".getBytes(); // 10 bytes
23	        CountingInputStream counting = new CountingInputStream(new ByteArrayInputStream(data));
24	
25	        ControllableInputStream in = ControllableInputStream.wrap(counting, 5); // cap at 5 bytes
26	        byte[] buf = new byte[10];
27	
28	        int read = in.read(buf);
29	        assertEquals(5, read, "should only read up to cap");
30	        assertEquals(5, counting.count, "underlying stream should not be pulled past cap");
31	        assertFalse(in.baseReadFully(), "cap hit is not EOF");
32	
33	        int second = in.read(buf);
34	        assertEquals(-1, second, "further reads return -1 once cap is exhausted");
35	        assertFalse(in.baseReadFully(), "still not true EOF");
36	        assertTrue(in.isTruncated(), "content beyond the cap is a truncation");
37	        in.close();
