40	    @Test
41	    void compactsBufferWithActiveMark() throws IOException {
42	        int size = SharedConstants.DefaultBufferSize * 2;
43	        byte[] data = new byte[size];
44	        for (int i = 0; i < size; i++) data[i] = (byte) (i % 256);
45	
46	        ControllableInputStream in = ControllableInputStream.wrap(new ByteArrayInputStream(data), 0);
47	
48	        byte[] first = new byte[500];
49	        assertEquals(500, in.read(first));
50	
51	        in.mark(SharedConstants.DefaultBufferSize); // mark at logical pos 500
52	
53	        byte[] consume = new byte[SharedConstants.DefaultBufferSize];
54	        int firstRead = in.read(consume); // serves remainder of current buffer (BufferSize - 500)
55	        assertEquals(SharedConstants.DefaultBufferSize - 500, firstRead);
56	
57	        byte[] more = new byte[1000];
58	        int secondRead = in.read(more); // triggers fill() with active mark, then consumes from freshly filled buffer
59	        assertEquals(SharedConstants.DefaultBufferSize - firstRead, secondRead);
60	
61	        in.reset(); // should rewind to mark despite prior compaction
62	
63	        byte[] reread = new byte[1000];
64	        assertEquals(1000, in.read(reread));
65	        for (int i = 0; i < reread.length; i++) {
66	            assertEquals(data[500 + i], reread[i], "byte mismatch at " + i);
67	        }
68	        in.close();
