73	    /** records every progress event for assertions */
74	    private static final class ProgressEvents implements Progress<ControllableInputStream> {
75	        final List<Event> events = new ArrayList<>();
76	
77	        @Override public void onProgress(int processed, int total, float percent, ControllableInputStream context) {
78	            events.add(new Event(processed, total, percent));
79	        }
80	
81	        int size() { return events.size(); }
82	        Event last() { return events.get(events.size() - 1); }
83	        Event first() { return events.get(0); }
84	
85	        long countOf(float percent) {
86	            return events.stream().filter(e -> e.percent == percent).count();
87	        }
88	
89	        void assertMonotonic() {
90	            int lastProcessed = -1;
91	            float lastPercent = -1f;
92	            for (Event e : events) {
93	                assertTrue(e.processed >= lastProcessed, "processed went backwards: " + lastProcessed + " -> " + e.processed);
94	                assertTrue(e.percent >= lastPercent, "percent went backwards: " + lastPercent + " -> " + e.percent);
95	                lastProcessed = e.processed;
96	                lastPercent = e.percent;
97	            }
98	        }
99	    }
100	
101	    private static final class Event {
102	        final int processed;
103	        final int total;
104	        final float percent;
105	
106	        Event(int processed, int total, float percent) {
107	            this.processed = processed;
108	            this.total = total;
109	            this.percent = percent;
110	        }
111	
112	        @Override public boolean equals(Object o) {
113	            if (this == o) return true;
114	            if (!(o instanceof Event)) return false;
115	            Event event = (Event) o;
116	            return processed == event.processed && total == event.total && Float.compare(event.percent, percent) == 0;
117	        }
118	
119	        @Override public int hashCode() {
120	            return java.util.Objects.hash(processed, total, percent);
121	        }
122	
123	        @Override public String toString() {
124	            return "Event{processed=" + processed + ", total=" + total + ", percent=" + percent + '}';
125	        }
126	    }
