135	    @Test
136	    void knownLengthProgressIsMonotonicAndCompletesOnce() throws IOException {
137	        int size = 10_000;
138	        byte[] data = new byte[size];
139	        ControllableInputStream in = ControllableInputStream.wrap(new ByteArrayInputStream(data), 0);
140	        ProgressEvents progress = new ProgressEvents();
141	        in.onProgress(size, true, progress, in);
142	
143	        readAll(in);
144	
145	        assertTrue(progress.size() >= 2, "expected an initial and a terminal event at minimum");
146	        assertEquals(new Event(0, size, 0f), progress.first());
147	        progress.assertMonotonic();
148	        for (Event e : progress.events) assertEquals(size, e.total, "declared total must hold");
149	        assertEquals(1, progress.countOf(100f), "exactly one completion event");
150	        Event terminal = progress.last();
151	        assertEquals(size, terminal.processed);
152	        assertEquals(size, terminal.total);
153	        assertEquals(100f, terminal.percent);
154	    }
