156	    @Test
157	    void unknownLengthStaysAtZeroUntilSingleCompletion() throws IOException {
158	        int size = 10_000;
159	        byte[] data = new byte[size];
160	        ControllableInputStream in = ControllableInputStream.wrap(new ByteArrayInputStream(data), 0);
161	        ProgressEvents progress = new ProgressEvents();
162	        in.onProgress(-1, true, progress, in);
