168	            assertEquals(-1, e.total, "an unknown length stays -1 on every event, including completion");
169	        for (int i = 0; i < progress.events.size() - 1; i++) {
170	            Event e = progress.events.get(i);
171	            assertEquals(0f, e.percent, "percent stays 0 until the confirmed end");
172	        }
