182	        // declared zero length: a single terminal event, no leading 0% event
183	        ControllableInputStream zero = ControllableInputStream.wrap(new ByteArrayInputStream(new byte[0]), 0);
184	        ProgressEvents zeroProgress = new ProgressEvents();
185	        zero.onProgress(0, true, zeroProgress, zero);
186	        readAll(zero);
