302	        long size = (long) Integer.MAX_VALUE + 1;
303	        ControllableInputStream in = ControllableInputStream.wrap(new VirtualInputStream(size), 0);
304	        AtomicInteger lastProcessed = new AtomicInteger(-1);
305	        AtomicBoolean negative = new AtomicBoolean(false);
