430	    /** throws a RuntimeException on its nth (1-based) event, but counts every event it actually receives */
431	    private static final class ExplodingProgress implements Progress<ControllableInputStream> {
432	        final AtomicInteger calls = new AtomicInteger();
433	        final int failOnCall;
