532	        CountingInputStream(InputStream in) {
533	            super(in);
534	        }
535	
536	        @Override
537	        public int read(byte[] b, int off, int len) throws IOException {
538	            int r = super.read(b, off, len);
539	            if (r > 0) count += r;
540	            return r;
541	        }
542	
543	        @Override
