559	        @Override
560	        public int read(byte[] b, int off, int len) throws IOException {
561	            if (remaining <= 0) throw new IOException("boom");
562	            int read = Math.min(remaining, len);
563	            remaining -= read;
564	            return read;
565	        }
566	
567	        @Override
568	        public int read() throws IOException {
