            .header(EchoRoute.CodeParam, "500")
            .ignoreHttpErrors(false)
            .onResponseProgress(failing)
            .execute();
        fail("expected an HttpStatusException");
    } catch (HttpStatusException e) {
        assertEquals(500, e.getStatusCode());
