import org.jsoup.internal.ControllableInputStream;
import org.jsoup.Progress;
import java.io.*;
import java.util.*;

public class Probe {
    // stream that returns 0 (short read) on the first two attempts, then data, then EOF
    static class FlakyStream extends InputStream {
        int zeros; int remaining;
        FlakyStream(int zeros, int data) { this.zeros = zeros; this.remaining = data; }
        @Override public int read() throws IOException {
            if (remaining <= 0) return -1;
            remaining--; return 0;
        }
        @Override public int read(byte[] b, int off, int len) {
            if (zeros > 0) { zeros--; return 0; } // spurious short read with len>0
            if (remaining <= 0) return -1;
            int r = Math.min(remaining, len); remaining -= r; return r;
        }
    }
    public static void main(String[] args) throws Exception {
        int size = 10000;
        ControllableInputStream in = ControllableInputStream.wrap(new FlakyStream(2, size), 0);
        List<String> ev = new ArrayList<>();
        in.onProgress(size, true, (Progress<ControllableInputStream>)(p,t,pct,c) -> ev.add(p+"/"+t+"/"+pct), in);
        byte[] buf = new byte[4096]; int total=0, r;
        while ((r = in.read(buf)) != -1) total += r;
        System.out.println("delivered="+total+" expected="+size);
        System.out.println("events="+ev.size());
        System.out.println("last="+ev.get(ev.size()-1));
        long comp = ev.stream().filter(e->e.endsWith("/100.0")).count();
        System.out.println("completions="+comp);
    }
}
